package server

// themeBoot resolves the theme before the first paint. It is served from
// /theme.js and loaded render-blocking in the head: the page's CSP allows
// script-src 'self' only, so it cannot be inlined, and deferring it would let
// a reviewer who has pinned a theme against their OS preference see the other
// one flash first. Storage is optional: a reviewer with it blocked still gets
// the OS preference and a toggle that works for the life of the page.
const themeBoot = `(()=>{const r=document.documentElement,k='change-saga-theme';
let stored=null;try{stored=localStorage.getItem(k)}catch{}
if(stored==='dark'||stored==='light')r.dataset.theme=stored;
const dark=()=>r.dataset.theme?r.dataset.theme==='dark':matchMedia('(prefers-color-scheme:dark)').matches;
const sync=b=>{if(b){b.setAttribute('aria-pressed',String(dark()));b.title=dark()?'Switch to light mode':'Switch to dark mode'}};
addEventListener('DOMContentLoaded',()=>sync(document.querySelector('[data-theme-toggle]')));
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-theme-toggle]');if(!b)return;
const next=dark()?'light':'dark';r.dataset.theme=next;try{localStorage.setItem(k,next)}catch{}sync(b)})})()`

// pageTemplate renders the whole reviewer surface. Chrome text stays in the
// reviewer's vocabulary: chapters, files, changes, comments. Storage and format
// vocabulary (fragments, sections, media types, schema versions, manifests)
// belongs to the CLI and the validator, not to this page. Authored saga content
// is rendered verbatim and may of course discuss the format itself.
var pageTemplate = `{{define "page"}}<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="change-saga-mutation-token" content="{{.MutationToken}}">
<title>{{.Saga.Manifest.Title}} · Change Saga</title>
<style>` + pageStyles + `</style><script src="/theme.js"></script><script src="/app.js" defer></script></head><body data-saga-id="{{.Saga.Manifest.ID}}" data-review-decided="{{.ReviewDecided}}" data-review-total="{{.ReviewTotal}}">` + iconSprite + `
<header class="topbar"><div class="brand">{{template "icon" "book"}}<span>change-saga</span></div>{{if .SlideNative}}<button type="button" class="icon-button slide-sidebar-toggle" data-slide-sidebar-toggle aria-expanded="true" aria-controls="changed-files-panel" aria-label="Hide slide navigator" title="Hide slide navigator">{{template "icon" "panel-left"}}</button>{{end}}<div class="view-tabs" role="tablist" aria-label="Workspace"><button type="button" role="tab" id="view-tab-saga" class="view-tab active" data-view-tab="saga" aria-controls="view-saga" aria-selected="true" tabindex="0" title="Read the story">{{template "icon" "list"}}Saga</button><button type="button" role="tab" id="view-tab-code" class="view-tab" data-view-tab="code" aria-controls="view-code" aria-selected="false" tabindex="-1" title="Review the complete comparison">{{template "icon" "diff"}}Code Diff</button><button type="button" role="tab" id="view-tab-manifest" class="view-tab" data-view-tab="manifest" aria-controls="view-manifest" aria-selected="false" tabindex="-1" title="Trace changes to the story and back">{{template "icon" "check"}}Coverage</button></div><button type="button" class="view-tab activity-trigger" data-open-activity data-activity-href="/api/activity" aria-controls="review-drawer" aria-expanded="false" title="Read review decisions and comment history">{{template "icon" "comment"}}Activity{{if .ActivityCount}}<span class="view-tab-count">{{.ActivityCount}}</span>{{end}}</button>{{if .SlideNative}}<button type="button" class="view-tab slide-present" data-slide-present aria-pressed="false" title="Present the current slide fullscreen">Present</button>{{end}}<div class="top-meta" data-code-meta hidden></div>{{if .ReviewItems}}<nav class="review-progress" data-review-progress aria-label="Review progress: {{.ReviewDecided}} of {{.ReviewTotal}} decisions">{{range .ReviewItems}}<a class="review-progress-segment {{.StateClass}}" data-review-progress-target="{{.Target}}" data-review-state="{{.State}}" data-review-progress-title="{{.Title}}" data-review-progress-note="{{.Note}}" href="{{.Href}}" aria-label="{{.Title}}: {{.Status}}{{if .Note}}. Comment: {{.Note}}{{end}}" title="{{.Title}} · {{.Status}}{{if .Note}}&#10;{{.Note}}{{end}}"></a>{{end}}<span class="review-progress-tooltip" data-review-progress-tooltip role="tooltip" hidden><span class="review-progress-tooltip-head"><strong data-review-progress-tooltip-title></strong><span data-review-progress-tooltip-status></span></span><span class="review-progress-tooltip-note" data-review-progress-tooltip-note hidden></span></span></nav>{{end}}<button type="button" class="icon-button theme-toggle" data-theme-toggle aria-pressed="false" aria-label="Toggle dark mode" title="Switch to dark mode">{{template "icon" "half"}}</button></header>
<div class="shell{{if .SlideNative}} slide-shell{{end}}" data-shell><aside class="sidebar{{if .SlideNative}} slide-sidebar{{end}}" id="changed-files-panel">{{if .SlideNative}}{{template "slide-sidebar" .Root}}{{else}}<a class="sidebar-title" href="/">{{template "icon" "book"}}<span>{{.Saga.Manifest.Title}}</span></a><div class="saga-side"><nav class="doc-tree" aria-label="Contents">{{template "doc-tree" .Nav}}</nav></div>{{end}}<div class="code-side" data-code-sidebar hidden><div class="surface-placeholder compact" role="status" aria-live="polite"><span class="surface-spinner" aria-hidden="true"></span><span>Changed files load when Code Diff opens.</span></div></div></aside>
<main class="content"><div class="view active" id="view-saga" role="tabpanel" aria-labelledby="view-tab-saga" data-view="saga">{{if .Error}}<div class="alert" role="alert">{{template "icon" "alert"}}<span><strong>Review readiness check failed</strong>{{.Error}}</span></div>{{else if .Diagnostic}}<div class="alert" role="alert">{{template "icon" "alert"}}<span><strong>Review readiness check failed</strong>{{.Diagnostic}}</span></div>{{end}}{{if .SlideNative}}{{template "slide-native" .Root}}{{else}}<header class="page-heading"><h2>{{.Saga.Manifest.Title}}</h2>{{with .CoverageTotals}}<p class="coverage-totals" data-coverage-totals>{{.Files}} {{if eq .Files 1}}file{{else}}files{{end}} · {{.Total}} changed {{if eq .Total 1}}line{{else}}lines{{end}} · {{.Covered}} explained{{if .Uncovered}} · <span class="gap">{{.Uncovered}} unexplained</span>{{end}}</p>{{else}}<p class="coverage-totals loading" data-coverage-loading role="status">Building the review index… Coverage will update when it is ready.</p>{{end}}</header>{{template "overview" .Root}}<section class="chapter-index"><h2>Chapters</h2><div class="chapter-pages">{{range .Root.ChildViews}}{{if eq .Kind "chapter"}}{{template "chapter" .}}{{else}}{{template "section" .}}{{end}}{{end}}</div></section>{{end}}</div>
<div class="view" id="view-code" role="tabpanel" aria-labelledby="view-tab-code" data-view="code" data-review-surface="code" data-surface-href="/api/code"><div class="surface-placeholder" role="status" aria-live="polite" data-surface-status><span class="surface-spinner" aria-hidden="true"></span><strong>Code Diff is ready when you open it.</strong><span>The comparison stays out of the initial page.</span></div></div></main></div>
<main class="manifest-view view" id="view-manifest" role="tabpanel" aria-labelledby="view-tab-manifest" data-view="manifest" data-review-surface="manifest" data-surface-href="/api/coverage"><div class="surface-placeholder" role="status" aria-live="polite" data-surface-status><span class="surface-spinner" aria-hidden="true"></span><strong>Coverage loads when you open it.</strong><span>Files appear automatically as they are ready.</span></div></main>
<div class="annotation-toolbox" id="annotation-toolbox" role="toolbar" aria-label="Annotation tools" data-annotation-target hidden><span class="tool-target" data-tool-target></span><button type="button" class="icon-button history-button" data-undo disabled aria-label="Nothing to undo" title="Undo (Ctrl/Cmd+Z)">{{template "icon" "undo"}}</button><button type="button" class="icon-button history-button" data-redo disabled aria-label="Nothing to redo" title="Redo (Ctrl+Y or Ctrl/Cmd+Shift+Z)">{{template "icon" "redo"}}</button><span class="tool-divider" aria-hidden="true"></span><button type="button" class="icon-button" data-tool="select" aria-pressed="true" aria-label="Select" title="Select">{{template "icon" "cursor"}}</button><button type="button" class="icon-button" data-tool="target" aria-pressed="false" aria-label="Comment" title="Comment">{{template "icon" "comment"}}</button><button type="button" class="icon-button" data-tool="text" aria-pressed="false" aria-label="Highlight selected text" title="Highlight">{{template "icon" "marker"}}</button><button type="button" class="icon-button" data-tool="rect" aria-pressed="false" aria-label="Rectangle" title="Rectangle">{{template "icon" "square"}}</button><button type="button" class="icon-button" data-tool="draw" aria-pressed="false" aria-label="Freehand" title="Freehand">{{template "icon" "pen"}}</button><button type="button" class="icon-button" data-tool="sticky" aria-pressed="false" aria-label="Sticky note" title="Sticky note">{{template "icon" "note"}}</button><label class="annotation-color" title="Annotation color"><span class="sr-only">Annotation color</span><input type="color" data-annotation-color value="#d04832" aria-label="Annotation color"></label><span class="annotation-selection-tools" data-annotation-selection hidden><button type="button" class="icon-button" data-remove-annotation aria-label="Delete selected annotation" title="Delete (Del)">{{template "icon" "trash"}}</button></span></div>
<form class="dialog annotation-compose" method="post" action="/api/thread" enctype="multipart/form-data"><input type="hidden" name="target"><input type="hidden" name="anchor"><input type="hidden" name="kind" value="comment"><div class="dialog-head"><h2>Add a comment</h2><button type="button" class="icon-button" data-close-annotation aria-label="Cancel" title="Cancel">{{template "icon" "close"}}</button></div><div class="dialog-form"><textarea name="body" placeholder="Start a review thread" aria-label="Comment"></textarea><div class="dialog-actions"><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" aria-label="Attach files" multiple><button class="btn-primary" type="submit">Comment</button></div></div></form>
<form class="review-decision-compose" data-review-decision-form data-shared-review-form method="post" action="/api/review" hidden><input type="hidden" name="target"><input type="hidden" name="state"><textarea name="body" placeholder="Optional note" aria-label="Optional review note"></textarea><div><button class="btn-primary" type="submit">Submit</button><button class="icon-button" type="button" data-review-cancel aria-label="Cancel" title="Cancel">{{template "icon" "close"}}</button></div></form>
<div class="drawer-backdrop" data-close-drawer></div><aside class="diff-drawer" id="review-drawer" aria-hidden="true" inert aria-label="Linked code"><div class="drawer-head">{{template "icon" "diff"}}<strong id="review-drawer-title">Linked code</strong><button type="button" class="icon-button" data-close-drawer aria-label="Close linked code" title="Close">{{template "icon" "close"}}</button></div><div class="drawer-body"></div></aside>
<form class="diff-compose" method="post" action="/api/thread" enctype="multipart/form-data"><input type="hidden" name="target"><input type="hidden" name="anchor"><input type="hidden" name="kind" value="comment"><div class="diff-compose-head"><strong>Comment on this change</strong><button type="button" class="icon-button" data-close-diff-compose aria-label="Cancel" title="Cancel">{{template "icon" "close"}}</button></div><div class="diff-compose-fields"><textarea name="body" placeholder="What should the author know?"></textarea><button class="btn-primary" type="submit">Add</button><textarea class="replacement" name="replacement" placeholder="Replacement code"></textarea><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" aria-label="Attach files" multiple></div></form>
</body></html>{{end}}

{{define "icon"}}<svg class="i" aria-hidden="true" focusable="false"><use href="#i-{{.}}"></use></svg>{{end}}
{{define "ficon"}}<svg class="ficon" aria-hidden="true" focusable="false"><use href="#{{fileIcon .}}"></use></svg>{{end}}

{{define "slide-mini-media"}}{{if eq .MediaType "text/html"}}<iframe tabindex="-1" sandbox="allow-scripts" loading="lazy" src="{{.URL}}" title=""></iframe>{{else}}<img loading="lazy" src="{{.URL}}" alt="">{{end}}{{end}}
{{define "slide-reference"}}<a class="related-slide" href="{{.Href}}" data-open-fragment="{{.Anchor}}" aria-label="Open slide: {{.Title}}"><span class="related-slide-preview" aria-hidden="true">{{template "slide-mini-media" .}}</span><span class="related-slide-caption"><strong>{{.Title}}</strong><span class="slide-thumbnail-status" role="img" data-slide-review-status data-review-target="{{.Target}}" data-review-state="{{.ReviewState}}" aria-label="{{if eq .ReviewState "approved"}}Approved{{else if eq .ReviewState "rejected"}}Changes requested{{else}}Not reviewed{{end}}" title="{{if eq .ReviewState "approved"}}Approved{{else if eq .ReviewState "rejected"}}Changes requested{{else}}Not reviewed{{end}}"></span></span>{{if .ItemCount}}<small>{{.ItemCount}} linked {{if eq .ItemCount 1}}item{{else}}items{{end}}</small>{{end}}</a>{{end}}
{{define "related-saga-groups"}}{{range .}}<section class="related-chapter{{if .SlideNative}} related-deck{{end}}">{{if .SlideNative}}<h3 class="related-chapter-link">{{.Title}}</h3>{{else}}<a class="related-chapter-link" href="{{.Href}}">{{.Title}}</a>{{end}}<div class="related-group-items">{{range .Fragments}}{{if .Slide}}{{template "slide-reference" .Slide}}{{else}}<a class="related-fragment" href="{{.Href}}" data-open-fragment="{{.Anchor}}"><strong>{{.Title}}</strong>{{if .Excerpt}}<span>{{.Excerpt}}</span>{{end}}</a>{{end}}{{end}}</div></section>{{end}}{{end}}
{{define "activity-target-link"}}<a class="activity-target{{if .Slide}} activity-slide-target{{end}}" href="{{.Href}}">{{if .Slide}}<span class="activity-slide-preview" aria-hidden="true">{{template "slide-mini-media" .Slide}}</span><span class="activity-slide-copy"><span>{{.TargetKind}}</span><strong>{{.Slide.Title}}</strong>{{if ne .TargetTitle .Slide.Title}}<small>{{.TargetTitle}}</small>{{else if .TargetContext}}<small>{{.TargetContext}}</small>{{end}}</span>{{else}}<span>{{.TargetKind}}</span><strong>{{.TargetTitle}}</strong>{{if .TargetContext}}<small>{{.TargetContext}}</small>{{end}}{{end}}{{template "icon" "arrow-right"}}</a>{{end}}
{{define "manifest-owner-reference"}}{{if .Href}}<a href="{{.Href}}"{{if .Slide}} class="manifest-slide-owner"{{end}}>{{if .Slide}}<span class="manifest-slide-preview" aria-hidden="true">{{template "slide-mini-media" .Slide}}</span><span class="manifest-slide-copy"><strong>{{.Slide.Title}}</strong><small>{{if ne .Title .Slide.Title}}{{.Title}}{{if .Chapter}} · {{end}}{{end}}{{.Chapter}}</small></span>{{else}}{{template "icon" "book"}}<strong>{{.Title}}</strong>{{if .Chapter}}<small>{{.Chapter}}</small>{{end}}{{end}}</a>{{else}}<span class="manifest-owner-missing">{{.Title}}</span>{{end}}{{end}}

{{define "activity-view"}}<div data-review-surface-response="activity"><div class="activity-wrap"><header class="activity-heading"><div><p class="eyebrow">Review history</p><h1>Activity{{if .ScopeTitle}} for {{.ScopeTitle}}{{end}}</h1><p>{{if .ScopeTitle}}Decisions and conversations on this {{.ScopeKind | lower}}. <a href="/?activity=1">Show all activity</a>{{else}}Every decision and conversation recorded in this saga, newest first.{{end}}</p></div><div class="activity-summary"><strong>{{.Threads}}</strong> {{if eq .Threads 1}}thread{{else}}threads{{end}} · <strong>{{.Decisions}}</strong> {{if eq .Decisions 1}}decision{{else}}decisions{{end}}</div></header><div class="activity-toolbar" role="toolbar" aria-label="Filter review activity"><button type="button" data-activity-filter="all" aria-pressed="true">All <span>{{.Total}}</span></button><button type="button" data-activity-filter="open" aria-pressed="false">Open <span>{{.Open}}</span></button><button type="button" data-activity-filter="resolved" aria-pressed="false">Resolved <span>{{.Resolved}}</span></button><button type="button" data-activity-filter="decision" aria-pressed="false">Decisions <span>{{.Decisions}}</span></button></div><div class="activity-list" data-activity-list>{{range .Items}}{{$item := .}}<article class="activity-card {{.Kind}} {{.State}}" id="{{.DOMID}}" data-activity-item data-activity-kind="{{.Kind}}" data-activity-state="{{.Filter}}" data-activity-target="{{.Target}}"><header class="activity-card-head"><div class="activity-card-title"><span class="activity-kind">{{.KindLabel}}</span><span class="activity-state {{.State}}">{{.StateLabel}}</span></div>{{template "activity-target-link" .}}</header><div class="activity-attribution"><span title="{{.AttributionDetail}}">{{if .Author}}{{.Author}}{{else}}Unattributed reviewer{{end}}</span><time datetime="{{.CreatedAt.Format "2006-01-02T15:04:05Z07:00"}}">{{.CreatedAt.Format "2006-01-02 15:04 MST"}}</time></div>{{if eq .Kind "decision"}}{{if .Body}}<div class="activity-body fragment-markdown">{{.Body}}</div>{{else}}<p class="activity-empty-note">No review note was recorded.</p>{{end}}{{else}}{{$thread := .Thread}}<div class="activity-conversation">{{range $index,$message := $thread.Messages}}<div class="activity-message{{if $index}} reply{{end}}"><div class="activity-message-head" title="{{$message.AttributionDetail}}"><strong>{{if $message.Author}}{{$message.Author}}{{else}}Unattributed reviewer{{end}}</strong><time datetime="{{$message.CreatedAt.Format "2006-01-02T15:04:05Z07:00"}}">{{$message.CreatedAt.Format "2006-01-02 15:04 MST"}}</time></div><div class="activity-message-body">{{template "message-fragments" (index $thread.MessageViews $index)}}</div></div>{{end}}</div>{{if $thread.Events}}<ol class="activity-events" aria-label="Thread state history">{{range $thread.Events}}{{if .State}}<li><span class="activity-event-state">{{.State}}</span><span title="{{.AttributionDetail}}">{{if .Author}}{{.Author}}{{else}}Unattributed reviewer{{end}}</span><time datetime="{{.CreatedAt.Format "2006-01-02T15:04:05Z07:00"}}">{{.CreatedAt.Format "2006-01-02 15:04 MST"}}</time></li>{{end}}{{end}}</ol>{{end}}{{end}}</article>{{else}}<div class="activity-empty"><strong>No review activity yet.</strong><span>Decisions and comments will appear here as reviewers work through the saga.</span></div>{{end}}<p class="activity-filter-empty" data-activity-filter-empty hidden>No activity matches this filter.</p></div></div></div>{{end}}

{{define "code-view"}}<div data-review-surface-response="code"><div data-code-sidebar-content><div class="tree-tools"><label class="tree-search">{{template "icon" "search"}}<input type="search" data-file-filter placeholder="Filter files" aria-label="Filter changed files"></label><button type="button" class="icon-button" data-toggle-tree aria-label="Hide file tree" title="Hide file tree">{{template "icon" "panel-left"}}</button></div><label class="tree-filter-check"><input type="checkbox" data-hide-reviewed> Hide reviewed files</label><p class="tree-summary" data-tree-summary>{{.Tree.ReviewedCount}}/{{.Tree.FileCount}} reviewed · {{template "diff-counts" .Tree}}</p><div class="file-tree" role="tree" aria-label="Changed files" data-page-items="files">{{template "file-tree-nodes" .Tree.Nodes}}</div><p class="tree-empty" data-tree-empty hidden>No files match this filter.</p></div><div data-code-panel-content><span data-code-meta-content hidden>{{.ReviewedFiles}}/{{len .Files}} reviewed</span><div class="code-toolbar" role="toolbar" aria-label="Code review layout"><button type="button" class="icon-button" data-toggle-tree aria-controls="changed-files-panel" aria-pressed="true" aria-label="Toggle file tree" title="File tree">{{template "icon" "panel-left"}}</button><span class="tool-divider" aria-hidden="true"></span><button type="button" class="icon-button" data-layout="inline" aria-pressed="true" aria-label="Unified diff" title="Unified">{{template "icon" "inline"}}</button><button type="button" class="icon-button" data-layout="split" aria-pressed="false" aria-label="Side-by-side diff" title="Side by side">{{template "icon" "split"}}</button><span class="spacer"></span><span class="metric">{{.ReviewedFiles}}/{{len .Files}} reviewed</span><button type="button" class="icon-button" data-toggle-related aria-controls="related-saga-panel" aria-pressed="true" aria-label="Toggle explanations panel" title="Explained by">{{template "icon" "panel-right"}}</button></div><div class="code-workspace" data-code-workspace><div class="code-main">{{if .SelectedFile}}{{template "file-diff-shell" .}}{{else}}<div class="remaining">No product code changes in this comparison.</div>{{end}}</div>{{if .SelectedFile}}<aside class="related-saga" id="related-saga-panel" aria-label="Explanations for this file"><div class="related-head"><h2>Explained by</h2><button type="button" class="icon-button" data-toggle-related aria-label="Hide explanations panel" title="Hide">{{template "icon" "close"}}</button></div>{{if .RelatedSaga}}{{template "related-saga-groups" .RelatedSaga}}{{else}}<p>{{.RelatedEmpty}}</p>{{end}}</aside>{{end}}</div></div></div>{{end}}

{{define "review-file-diff-surface"}}<div class="diff-surface" data-diff-surface data-layout="inline" data-file-path="{{.Path}}"><div class="review-file-diff-actions"><span data-file-diff-status role="status">Loading every changed hunk…</span>{{with .CodeHref}}<a href="{{.}}">Open in Code Diff{{template "icon" "arrow-right"}}</a>{{end}}</div><div class="diff-column-head" aria-hidden="true"><span class="split-label">Before</span><span class="split-label">After</span></div><div class="diff-lines" data-file-diff-rows data-diff-body data-page-items="lines"><p class="diff-placeholder" data-diff-placeholder>Loading changed hunks…</p></div><div class="diff-selection-toolbar" data-selection-toolbar role="toolbar" aria-label="Selected diff lines"><span data-selection-label></span><button type="button" class="icon-button" data-selection-action="comment" aria-label="Comment on the selected lines" title="Comment">{{template "icon" "comment"}}</button><button type="button" class="icon-button" data-selection-action="suggestion" aria-label="Suggest a replacement for the selected lines" title="Suggest">{{template "icon" "pen"}}</button><button type="button" class="icon-button" data-selection-clear aria-label="Clear selection" title="Clear">{{template "icon" "close"}}</button></div></div>{{end}}

{{define "file-diff-shell"}}{{with .SelectedFile}}<article class="file-diff" id="{{.ID}}" data-file-path="{{.Path}}" data-file-diff-href="/api/file-diff?file={{urlquery .Path}}{{with $.SelectedDiffURI}}&amp;diff={{urlquery .}}{{end}}"><header class="file-head">{{template "ficon" .Path}}<code>{{.Path}}</code>{{if .Reviewed}}<span class="reviewed-badge" title="{{.ReviewerDetail}}">{{template "icon" "check"}}Reviewed{{if .Reviewer}} · {{.Reviewer}}{{end}}</span>{{end}}<span class="counts">{{template "diff-counts" .}}</span><details class="file-review-menu"><summary aria-label="{{if .Reviewed}}Reviewed{{else}}Mark this file reviewed{{end}}" title="{{if .Reviewed}}Reviewed{{else}}Mark reviewed{{end}}">{{template "icon" "check"}}</summary><form class="file-review" method="post" action="/api/diff-review"><input type="hidden" name="uri" value="{{.URI}}"><input type="hidden" name="file" value="{{.ID}}"><p>{{if .Reviewed}}Move this file back to the review queue.{{else}}Mark this file complete.{{end}}</p><button class="btn-primary" name="state" value="{{if .Reviewed}}unreviewed{{else}}reviewed{{end}}">{{if .Reviewed}}Unmark reviewed{{else}}Mark reviewed{{end}}</button></form></details></header>{{template "review-file-diff-surface" (reviewDiffSurface .Path "")}}</article>{{end}}{{end}}

{{define "file-review-control"}}<details class="file-review-menu"><summary aria-label="{{if .Reviewed}}Reviewed{{else}}Mark this file reviewed{{end}}" title="{{if .Reviewed}}Reviewed{{else}}Mark reviewed{{end}}">{{template "icon" "check"}}</summary><form class="file-review" method="post" action="/api/diff-review"><input type="hidden" name="uri" value="{{.URI}}"><input type="hidden" name="file" value="{{.Path}}"><p>{{if .Reviewed}}Move this file back to the review queue.{{else}}Mark this file complete.{{end}}</p><button class="btn-primary" name="state" value="{{if .Reviewed}}unreviewed{{else}}reviewed{{end}}">{{if .Reviewed}}Unmark reviewed{{else}}Mark reviewed{{end}}</button></form></details>{{end}}

{{define "manifest-view"}}<div data-review-surface-response="manifest"><div class="manifest-wrap">
<div class="manifest-tools"><div class="manifest-modes" role="group" aria-label="Coverage direction"><button type="button" data-manifest-mode="code" aria-pressed="true">Code → Saga</button><button type="button" data-manifest-mode="saga" aria-pressed="false">Saga → Code</button></div><span class="manifest-metric">{{len .Files}} files · {{.Total}} changes</span><label class="tree-search">{{template "icon" "search"}}<input type="search" data-manifest-filter placeholder="Filter" aria-label="Filter coverage"></label></div>
{{if .Uncovered}}<div class="manifest-alert" role="alert">{{template "icon" "alert"}}<span><strong>{{.Uncovered}} {{if eq .Uncovered 1}}change is{{else}}changes are{{end}} missing from the story.</strong>Open the highlighted files below and explain them before review can complete.</span></div>{{end}}
<section class="manifest-panel" data-manifest-panel="code">{{if .Tree}}<div class="mtree">{{template "manifest-tree-nodes" .Tree}}</div>{{else}}<div class="manifest-empty">No source changes in this comparison.</div>{{end}}<p class="manifest-filter-empty" data-manifest-empty hidden>No files match this filter.</p></section>
<section class="manifest-panel" data-manifest-panel="saga" hidden><div class="mtree">{{range .Targets}}{{template "manifest-target" .}}{{else}}<div class="manifest-empty">Nothing in the story maps to source changes yet.</div>{{end}}</div><p class="manifest-filter-empty" data-manifest-empty hidden>Nothing matches this filter.</p></section>
{{if .Orphans}}<section class="manifest-orphans"><h2>Stale references</h2><p>These committed references no longer match the current comparison.</p>{{range .Orphans}}<div class="manifest-orphan">{{template "icon" "alert"}}<div><strong>{{.Owner.Title}}</strong><small>{{.Reason}}</small></div>{{if .Owner.Href}}<a href="{{.Owner.Href}}">Open</a>{{end}}</div>{{end}}</section>{{end}}</div></div>{{end}}

{{define "manifest-tree-nodes"}}{{range .}}{{if eq .Kind "folder"}}<details class="manifest-folder" data-manifest-folder open style="--depth:{{.Depth}}"><summary>{{template "twisty"}}{{template "icon" "folder"}}<span class="mfile-name">{{.Name}}</span><span class="manifest-file-stats">{{template "diff-counts" .}}{{if .Uncovered}} · <span class="gap">{{.Uncovered}} unexplained</span>{{end}}</span></summary><div>{{template "manifest-tree-nodes" .Children}}</div></details>{{else}}{{template "manifest-file" .}}{{end}}{{end}}{{end}}

{{define "manifest-file"}}{{with .File}}<details class="manifest-file {{if .Uncovered}}has-gap{{end}}" data-manifest-search="{{.Path}}" style="--depth:{{$.Depth}}"><summary>{{template "twisty"}}{{template "ficon" .Path}}<span class="mfile-name">{{$.Name}}</span><span class="manifest-file-stats">{{template "diff-counts" .}}{{if .Events}} · {{.Events}} file {{if eq .Events 1}}event{{else}}events{{end}}{{end}}{{if .Uncovered}} · <span class="gap">{{.Uncovered}} unexplained</span>{{end}}</span></summary><div class="manifest-file-detail" style="--depth:{{$.Depth}}">{{if .HasDiff}}{{template "manifest-diff-surface" .Path}}{{end}}<div class="manifest-map-heading">Explained by</div><div class="manifest-rows">{{range .Chunks}}{{template "manifest-code-chunk" .}}{{end}}</div></div></details>{{end}}{{end}}

{{define "twisty"}}<svg class="i twisty" aria-hidden="true" focusable="false"><use href="#i-chevron"></use></svg>{{end}}

{{define "manifest-code-chunk"}}<div class="manifest-row {{if not .Covered}}unmapped{{end}}"><a class="manifest-range" href="{{.Href}}"><span>{{.Label}}</span><small>{{.AtomCount}} {{if eq .AtomCount 1}}changed line{{else}}changed lines{{end}}</small></a><div class="manifest-owners">{{range .Owners}}{{template "manifest-owner-reference" .}}{{else}}<span class="manifest-gap">Not explained yet</span>{{end}}</div></div>{{end}}

{{define "manifest-diff-surface"}}<div class="manifest-file-diff diff-surface" data-diff-surface data-layout="inline" data-file-path="{{.}}" data-manifest-diff-href="/api/file-diff?view=manifest&amp;file={{urlquery .}}" aria-label="Diff for {{.}}"><div class="diff-lines" data-manifest-diff-rows><p class="diff-placeholder" data-diff-placeholder>Loading the file diff…</p></div></div>{{end}}

{{define "manifest-file-diff-context"}}{{range .Lines}}{{template "manifest-diff-row" .}}{{end}}{{end}}
{{define "manifest-file-diff-page"}}<div data-file-diff-page data-file-path="{{.File.Path}}" data-next-cursor="{{.NextCursor}}" data-has-more="{{.HasMore}}" data-returned="{{.Returned}}"><div data-page-items="lines">{{template "manifest-file-diff-context" .File}}</div></div>{{end}}
{{define "file-diff-page"}}<div data-file-diff-page data-file-path="{{.File.Path}}" data-next-cursor="{{.NextCursor}}" data-has-more="{{.HasMore}}" data-returned="{{.Returned}}"><div data-page-items="lines">{{range .File.Lines}}{{template "diff-surface-row" .}}{{end}}</div></div>{{end}}

{{define "coverage-page"}}
<section data-review-surface-response="manifest" data-review-surface-page data-page-key="coverage" data-coverage-page data-mode="{{.Mode}}" data-next-cursor="{{.NextCursor}}" data-has-more="{{.HasMore}}" data-returned="{{.Returned}}" data-total="{{.Summary.Total}}" data-covered="{{.Summary.Covered}}" data-uncovered="{{.Summary.Uncovered}}" data-overlapping="{{.Summary.Overlapping}}" data-orphaned="{{.Summary.Orphaned}}" data-complete="{{.Summary.Complete}}">
  <div class="manifest-wrap">
    <div class="manifest-tools"><div class="manifest-modes" role="group" aria-label="Coverage direction"><button type="button" data-manifest-mode="code" aria-pressed="{{if eq .Mode "code"}}true{{else}}false{{end}}">Code → Saga</button><button type="button" data-manifest-mode="saga" aria-pressed="{{if eq .Mode "saga"}}true{{else}}false{{end}}">Saga → Code</button></div><span class="manifest-metric">{{.Summary.Files}} files · {{.Summary.Total}} changes</span><label class="tree-search">{{template "icon" "search"}}<input type="search" data-manifest-filter placeholder="Filter" aria-label="Filter coverage"></label></div>
    <section class="manifest-panel" data-manifest-panel="{{.Mode}}"><div data-page-items="coverage">
      {{if eq .Mode "code"}}<div class="mtree">{{range .Code}}
        <details class="manifest-page-row manifest-file {{if .File.Uncovered}}has-gap{{end}}" data-manifest-search="{{.File.Path}}" data-coverage-file-href="/api/coverage-file?file={{urlquery .File.Path}}"><summary>{{template "twisty"}}{{template "ficon" .File.Path}}<span class="mfile-name">{{.File.Path}}</span><span class="manifest-file-stats">{{template "diff-counts" .File}}{{if .File.Uncovered}} · <span class="gap">{{.File.Uncovered}} unexplained</span>{{end}}</span></summary><div class="manifest-file-detail">{{template "manifest-diff-surface" .File.Path}}<div class="manifest-map-heading">Explained by</div><div data-coverage-file-mappings><p class="diff-placeholder">Coverage details load when opened.</p></div></div></details>
      {{end}}</div>{{else}}<div class="mtree">{{range .Saga}}
        <details class="manifest-page-row manifest-target" data-manifest-search="{{.Target.Title}} {{.Target.Chapter}}" data-coverage-target-href="/api/coverage-target?target={{urlquery .Target.Target}}"><summary>{{template "twisty"}}{{if .Target.Slide}}<span class="manifest-target-slide-preview" aria-hidden="true">{{template "slide-mini-media" .Target.Slide}}</span>{{else}}{{template "icon" "book"}}{{end}}<span class="manifest-target-title"><strong>{{if .Target.Slide}}{{.Target.Slide.Title}}{{else}}{{.Target.Title}}{{end}}</strong>{{if .Target.Slide}}<small>{{if ne .Target.Title .Target.Slide.Title}}{{.Target.Title}}{{if .Target.Chapter}} · {{end}}{{end}}{{.Target.Chapter}}</small>{{else if .Target.Chapter}}<small>{{.Target.Chapter}}</small>{{end}}</span><span class="manifest-file-stats">{{.AtomCount}} {{if eq .AtomCount 1}}change{{else}}changes{{end}} · {{.FileCount}} {{if eq .FileCount 1}}file{{else}}files{{end}}</span></summary><div class="manifest-target-files"><div data-coverage-target-files><p class="diff-placeholder">Linked files load when opened.</p></div><a class="manifest-open-saga" href="{{.Target.Href}}">{{template "icon" "arrow-right"}}Open in Saga</a></div></details>
      {{end}}</div>{{if .Orphans}}<section class="manifest-orphans"><h2>Stale references</h2>{{range .Orphans}}<div class="manifest-orphan">{{template "icon" "alert"}}<div><strong>{{.Owner.Title}}</strong><small>{{.Reason}}</small></div>{{if .Owner.Href}}<a href="{{.Owner.Href}}">Open</a>{{end}}</div>{{end}}</section>{{end}}{{end}}
    </div></section>
  </div>
</section>
{{end}}

{{define "coverage-file-page"}}<div data-coverage-file-response data-file="{{.File}}" data-next-cursor="{{.NextCursor}}" data-has-more="{{.HasMore}}" data-returned="{{.Returned}}"><div data-page-items="coverage-file">{{range .Chunks}}{{template "manifest-code-chunk" .}}{{end}}</div></div>{{end}}
{{define "coverage-target-page"}}<div data-coverage-target-response data-target="{{.Target}}" data-next-cursor="{{.NextCursor}}" data-has-more="{{.HasMore}}" data-returned="{{.Returned}}"><div data-page-items="target-files">{{range .Files}}{{template "manifest-target-file" .}}{{end}}</div></div>{{end}}

{{define "code-page"}}<section data-review-surface-response="code" data-review-surface-page data-page-key="files" data-code-page data-next-cursor="{{.NextCursor}}" data-has-more="{{.HasMore}}" data-returned="{{.Returned}}" data-total-files="{{.TotalFiles}}" data-reviewed-files="{{.ReviewedFiles}}"{{with .Selected}} data-file-path="{{.Path}}"{{end}}><div data-code-sidebar-content><div class="tree-tools"><label class="tree-search">{{template "icon" "search"}}<input type="search" data-file-filter placeholder="Filter files" aria-label="Filter changed files"></label><button type="button" class="icon-button" data-toggle-tree aria-label="Hide file tree" title="Hide file tree">{{template "icon" "panel-left"}}</button></div><label class="tree-filter-check"><input type="checkbox" data-hide-reviewed> Hide reviewed files</label><p class="tree-summary" data-tree-summary>{{.ReviewedFiles}}/{{.TotalFiles}} reviewed</p><div class="file-tree" role="tree" aria-label="Changed files" data-page-items="files">{{template "file-tree-nodes" .Tree.Nodes}}</div><p class="tree-empty" data-tree-empty hidden>No files match this filter.</p></div><div data-code-panel-content><span data-code-meta-content hidden>{{.ReviewedFiles}}/{{.TotalFiles}} reviewed</span><div class="code-toolbar" role="toolbar" aria-label="Code review layout"><button type="button" class="icon-button" data-toggle-tree aria-controls="changed-files-panel" aria-pressed="true" aria-label="Toggle file tree" title="File tree">{{template "icon" "panel-left"}}</button><span class="tool-divider" aria-hidden="true"></span><button type="button" class="icon-button" data-layout="inline" aria-pressed="true" aria-label="Unified diff" title="Unified">{{template "icon" "inline"}}</button><button type="button" class="icon-button" data-layout="split" aria-pressed="false" aria-label="Side-by-side diff" title="Side by side">{{template "icon" "split"}}</button><span class="spacer"></span><span class="metric">{{.ReviewedFiles}}/{{.TotalFiles}} reviewed</span><button type="button" class="icon-button" data-toggle-related aria-controls="related-saga-panel" aria-pressed="true" aria-label="Toggle explanations panel" title="Explained by">{{template "icon" "panel-right"}}</button></div><div class="code-workspace" data-code-workspace><div class="code-main">{{with .Selected}}<article class="file-diff" id="{{.ID}}" data-file-path="{{.Path}}" data-file-diff-href="/api/file-diff?file={{urlquery .Path}}"><header class="file-head">{{template "ficon" .Path}}<code>{{.Path}}</code>{{if .Reviewed}}<span class="reviewed-badge" title="{{.ReviewerDetail}}">{{template "icon" "check"}}Reviewed{{if .Reviewer}} · {{.Reviewer}}{{end}}</span>{{end}}<span class="counts">{{template "diff-counts" .}}</span>{{template "file-review-control" .}}</header>{{template "review-file-diff-surface" (reviewDiffSurface .Path "")}}</article>{{else}}<div class="remaining">No product code changes in this comparison.</div>{{end}}</div>{{if .Selected}}<aside class="related-saga" id="related-saga-panel" aria-label="Explanations for this file">{{range .Owners}}<section class="related-chapter">{{if .Chapter}}<a class="related-chapter-link" href="{{.Href}}">{{.Chapter}}</a>{{end}}<a class="related-fragment" href="{{.Href}}" data-open-fragment="{{.Href}}"><strong>{{.Title}}</strong></a></section>{{else}}<p>{{.RelatedEmpty}}</p>{{end}}</aside>{{end}}</div></div></section>{{end}}

{{define "manifest-diff-row"}}{{if eq .Kind "context"}}<div class="diff-row context"><span class="line-no">{{.OldLine}}</span><span class="line-no">{{.NewLine}}</span><span class="sign" aria-hidden="true"> </span><code class="code-line" data-code>{{.Content}}</code><span></span></div>{{else if eq .Kind "event"}}<div class="diff-row event"><span class="line-no">•</span><span class="line-no">•</span><span class="sign" aria-hidden="true">↳</span><span class="code-line">{{.Event}} {{if .OldPath}}{{.OldPath}} → {{.NewPath}}{{else}}{{.Path}}{{end}}</span><span></span></div>{{else}}<div class="diff-row {{.Kind}}"><span class="line-no">{{if .OldLine}}{{.OldLine}}{{end}}</span><span class="line-no">{{if .NewLine}}{{.NewLine}}{{end}}</span><span class="sign" aria-hidden="true">{{if eq .Kind "old"}}−{{else}}+{{end}}</span><code class="code-line" data-code>{{.Content}}</code><span></span></div>{{end}}{{end}}

{{define "manifest-target"}}<details class="manifest-target" data-manifest-search="{{.Title}} {{.Chapter}}"><summary>{{template "twisty"}}{{if .Slide}}<span class="manifest-target-slide-preview" aria-hidden="true">{{template "slide-mini-media" .Slide}}</span>{{else}}{{template "icon" "book"}}{{end}}<span class="manifest-target-title"><strong>{{if .Slide}}{{.Slide.Title}}{{else}}{{.Title}}{{end}}</strong>{{if .Slide}}<small>{{if ne .Title .Slide.Title}}{{.Title}}{{if .Chapter}} · {{end}}{{end}}{{.Chapter}}</small>{{else if .Chapter}}<small>{{.Chapter}}</small>{{end}}</span><span class="manifest-file-stats">{{.AtomCount}} {{if eq .AtomCount 1}}change{{else}}changes{{end}}</span></summary><div class="manifest-target-files">{{range .Files}}{{template "manifest-target-file" .}}{{end}}<a class="manifest-open-saga" href="{{.Href}}">{{template "icon" "arrow-right"}}Open in Saga</a></div></details>{{end}}

{{define "manifest-target-file"}}<details class="manifest-target-file"><summary>{{template "twisty"}}{{template "ficon" .Path}}<code>{{.Path}}</code><span class="manifest-file-stats">{{template "diff-counts" .}}{{if .Events}} · {{.Events}} file {{if eq .Events 1}}event{{else}}events{{end}}{{end}}</span></summary><div class="manifest-target-file-detail">{{if .HasDiff}}{{template "manifest-diff-surface" .Path}}{{end}}<div class="manifest-target-links"><span>Linked {{if eq (len .Chunks) 1}}range{{else}}ranges{{end}}</span>{{range .Chunks}}<a href="{{.Href}}">{{.Label}}</a>{{end}}<a class="manifest-full-diff" href="{{.Href}}">Open in Code Diff {{template "icon" "arrow-right"}}</a></div></div></details>{{end}}

{{define "doc-tree"}}{{range .}}<div class="doc-node"><div class="doc-row {{if .Active}}current{{end}}">{{if .Children}}<button type="button" class="doc-twisty" data-doc-twisty aria-expanded="{{.Expanded}}" aria-controls="{{.NodeID}}" aria-label="Toggle {{.Title}}">{{template "twisty"}}</button>{{else}}<span class="doc-twisty placeholder" aria-hidden="true">{{template "twisty"}}</span>{{end}}<a class="doc-link" href="{{.Href}}" title="{{.Title}}"{{if .Active}} aria-current="page"{{end}}>{{.Title}}</a>{{if .StateLabel}}<span class="doc-state {{.StateClass}}" title="{{.StateLabel}}"><span class="sr-only">{{.StateLabel}}</span>{{template "icon" .StateIcon}}</span>{{end}}</div>{{if .Children}}<div class="doc-children" id="{{.NodeID}}"{{if not .Expanded}} hidden{{end}}>{{template "doc-tree" .Children}}</div>{{end}}</div>{{end}}{{end}}

{{define "file-tree-nodes"}}{{range .}}{{if eq .Kind "folder"}}<details data-tree-folder {{if .Expanded}}open{{end}}><summary role="treeitem" style="--depth:{{.Depth}}">{{template "twisty"}}{{template "icon" "folder"}}<span class="tree-name">{{.Name}}</span></summary><div role="group">{{template "file-tree-nodes" .Children}}</div></details>{{else}}<a role="treeitem" data-tree-file data-tree-path="{{.File.Path}}" data-reviewed="{{.File.Reviewed}}" class="{{if .File.Reviewed}}reviewed{{end}} {{if .File.Selected}}selected{{end}}" href="{{.File.Href}}" style="--depth:{{.Depth}}" aria-current="{{if .File.Selected}}page{{else}}false{{end}}" title="{{.File.Path}}"><span class="tree-state">{{if .File.Reviewed}}<span class="sr-only">Reviewed</span>{{template "icon" "check"}}{{end}}</span>{{template "ficon" .File.Path}}<span class="tree-name">{{.Name}}</span><span class="counts">{{template "diff-counts" .File}}</span></a>{{end}}{{end}}{{end}}

{{define "permalink"}}<button class="permalink" type="button" data-copy-link="#{{.}}" aria-label="Copy link" title="Copy link">{{template "icon" "link"}}</button>{{end}}
{{define "review-controls"}}<div class="review-controls" data-review-controls data-review-target="{{.Target}}" data-review-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" data-review-state="{{.ReviewState}}" data-review-author="{{.ReviewAuthor}}" data-review-detail="{{.ReviewDetail}}"><span class="review-decision-note" data-review-note title="{{.ReviewBody}}"{{if not .ReviewBody}} hidden{{end}}>{{.ReviewBody}}</span>{{if .ReviewDecisions}}<span class="review-identities" data-review-identities>{{range .ReviewDecisions}}<span class="review-identity {{.State}} {{.Kind}}" data-reviewer-kind="{{.Kind}}" data-reviewer-author="{{.Author}}" data-reviewer-state="{{.State}}" title="{{.Detail}}{{if .Body}}&#10;{{.Body}}{{end}}"><span class="reviewer-kind">{{.KindLabel}}</span><span class="reviewer-author">{{if .Author}}{{.Author}}{{else}}Unattributed{{end}}</span>{{if eq .Kind "ai"}}<span class="reviewer-ai">{{.Name}} · {{.Agent}} · {{.Model}}</span>{{end}}</span>{{end}}</span>{{end}}<span class="review-decision-group"><button class="review-decision approve" type="button" data-review-decision="approved" aria-pressed="{{if eq .ReviewState "approved"}}true{{else}}false{{end}}" aria-label="{{if eq .ReviewState "approved"}}Approval recorded for{{else}}Approve{{end}} {{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}{{if and (eq .ReviewState "approved") .ReviewAuthor}} by {{.ReviewAuthor}}{{end}}{{if and (eq .ReviewState "approved") .ReviewBody}}. Comment: {{.ReviewBody}}{{end}}"{{if ne .ReviewState "approved"}} title="Approve"{{end}}><span class="review-icon-outline">{{template "icon" "approve"}}</span><span class="review-icon-filled">{{template "icon" "approve-filled"}}</span></button><button class="review-decision reject" type="button" data-review-decision="rejected" aria-pressed="{{if eq .ReviewState "rejected"}}true{{else}}false{{end}}" aria-label="{{if eq .ReviewState "rejected"}}Changes requested on{{else}}Request changes on{{end}} {{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}{{if and (eq .ReviewState "rejected") .ReviewAuthor}} by {{.ReviewAuthor}}{{end}}{{if and (eq .ReviewState "rejected") .ReviewBody}}. Comment: {{.ReviewBody}}{{end}}"{{if ne .ReviewState "rejected"}} title="Request changes"{{end}}><span class="review-icon-outline">{{template "icon" "reject"}}</span><span class="review-icon-filled">{{template "icon" "reject-filled"}}</span></button></span>{{template "review-comment-button" .}}</div>{{end}}
{{define "review-comment-button"}}<button class="icon-button review-comment" type="button" data-review-comment="{{.Target}}" data-review-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" aria-label="Comment on {{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" title="Comment">{{template "icon" "comment"}}</button>{{end}}
{{define "annotation-tools-button"}}<button class="icon-button annotation-tools-toggle" type="button" data-annotation-tools="{{.Target}}" data-annotation-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" aria-expanded="false" aria-controls="annotation-toolbox" aria-label="Show annotation tools for {{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" title="Annotate">{{template "icon" "marker"}}</button>{{end}}
{{define "chapter-review-directory"}}<details class="chapter-review-directory" data-chapter-review-directory open><summary><span class="review-directory-heading">{{template "twisty"}}{{template "icon" "check"}}Review this chapter</span><span class="review-directory-meta"><span class="review-directory-summary" data-review-directory-summary>{{.ReviewDirectoryDecided}}/{{len .ReviewDirectory}} reviewed</span><span class="review-directory-hint" aria-hidden="true"></span></span></summary>{{if .ReviewDirectory}}<ol class="review-directory-list">{{range .ReviewDirectory}}<li class="review-directory-item {{.StateClass}}" style="--review-depth:{{.Depth}}" data-review-directory-target="{{.Target}}" data-review-state="{{.State}}"><span class="review-directory-state" aria-hidden="true"></span><a href="{{.Href}}"><span class="review-directory-kind">{{.KindLabel}}</span><span class="review-directory-title">{{.Title}}</span></a><span class="review-directory-status" data-review-directory-status>{{.Status}}</span>{{if .ActivityHref}}<a class="review-directory-comments" href="{{.ActivityHref}}" aria-label="Open {{.CommentLabel}}" title="Open {{.CommentLabel}}">{{template "icon" "comment"}}{{.CommentCount}}</a>{{else}}<span class="review-directory-comments" aria-label="{{.CommentLabel}}" title="{{.CommentLabel}}">{{template "icon" "comment"}}{{.CommentCount}}</span>{{end}}{{template "review-controls" .}}</li>{{end}}</ol>{{else}}<p class="review-directory-empty">Nothing inside this chapter requires approval.</p>{{end}}</details>{{end}}
{{define "diff-counts"}}<span class="diff-counts"><span class="add">+{{.Added}}</span><span class="del">−{{.Deleted}}</span></span>{{end}}
{{define "diff-open-button"}}{{if lt .ChangeCount 0}}<button type="button" class="icon-button diff-button loading" data-target-code-href="/api/target-code?target={{urlquery .Target}}" data-target-code-template="diffs-{{.DOMID}}" aria-label="Load linked code for {{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" title="Linked code">{{template "icon" "diff"}}</button>{{else}}<button type="button" class="icon-button diff-button" data-open-diffs="diffs-{{.DOMID}}" aria-label="{{if and .Attached (gt .Attached.LineCount 0)}}Open linked code with {{.Attached.Added}} {{if eq .Attached.Added 1}}addition{{else}}additions{{end}} and {{.Attached.Deleted}} {{if eq .Attached.Deleted 1}}deletion{{else}}deletions{{end}}{{else}}Open the {{.ChangeCount}} linked code {{if eq .ChangeCount 1}}change{{else}}changes{{end}}{{end}}" title="Linked code">{{if and .Attached (gt .Attached.LineCount 0)}}{{template "diff-counts" .Attached}}{{else}}{{template "icon" "diff"}}{{.ChangeCount}}{{end}}</button>{{end}}{{end}}
{{define "diff-control"}}{{if .ChangeCount}}{{template "diff-open-button" .}}{{else if .HasDiffs}}<button type="button" class="icon-button diff-button loading" data-target-code-href="/api/target-code?target={{urlquery .Target}}" data-target-code-template="diffs-{{.DOMID}}" aria-label="Load linked code for {{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" title="Linked code">{{template "icon" "diff"}}</button>{{end}}{{end}}
{{define "target-code"}}<span data-target-code-response data-target-code-target="{{.Target}}" data-target-code-count="{{.ChangeCount}}">{{if .ChangeCount}}{{template "diff-open-button" .}}{{template "diff-template" .}}{{end}}</span>{{end}}

{{define "overview"}}<section id="{{.DOMID}}"><div class="section-actions">{{template "diff-control" .}}{{template "permalink" .DOMID}}{{template "review-controls" .}}</div>{{template "threads" .Threads}}{{range .FragmentViews}}{{template "fragment" .}}{{end}}{{if .ChangeCount}}{{template "diff-template" .}}{{end}}</section>{{end}}
{{define "slide-sidebar"}}<div class="saga-side slide-side"><a class="sidebar-title" href="/">{{template "icon" "book"}}<span>{{.Title}}</span></a><nav class="slide-rail" aria-label="Slides">{{range $deckIndex,$deck := .ChildViews}}<section class="slide-rail-deck"><h2>{{$deck.Title}}</h2><div class="slide-thumbnail-list">{{range $slideIndex,$slide := $deck.FragmentViews}}<div class="slide-thumbnail-card{{if and (eq $deckIndex 0) (eq $slideIndex 0)}} active{{end}}" data-slide-thumbnail-card data-review-state="{{$slide.ReviewState}}"><div class="slide-thumbnail-preview" aria-hidden="true">{{if eq $slide.MediaType "text/html"}}<iframe tabindex="-1" sandbox="allow-scripts" loading="lazy" src="{{$slide.URL}}" title=""></iframe>{{else}}<img loading="lazy" src="{{$slide.URL}}" alt="">{{end}}</div><span class="slide-thumbnail-caption"><span class="slide-thumbnail-title">{{$slide.Title}}</span><span class="slide-thumbnail-status" role="img" data-slide-review-status data-review-target="{{$slide.Target}}" data-review-state="{{$slide.ReviewState}}" aria-label="{{if eq $slide.ReviewState "approved"}}Approved{{else if eq $slide.ReviewState "rejected"}}Changes requested{{else}}Not reviewed{{end}}" title="{{if eq $slide.ReviewState "approved"}}Approved{{else if eq $slide.ReviewState "rejected"}}Changes requested{{else}}Not reviewed{{end}}"></span></span><button type="button" class="slide-thumbnail-hit" data-slide-thumbnail data-slide-target="{{$slide.Target}}" aria-current="{{if and (eq $deckIndex 0) (eq $slideIndex 0)}}true{{else}}false{{end}}" aria-label="Show slide: {{$slide.Title}}"></button></div>{{end}}</div></section>{{end}}</nav></div>{{end}}
{{define "slide-native"}}<section class="slide-native" data-slide-native aria-label="Slide review"><div class="slide-native-stage"><header class="slide-native-header" aria-live="polite"><span data-slide-position></span></header>{{range $deckIndex,$deck := .ChildViews}}{{range $slideIndex,$slide := $deck.FragmentViews}}<section class="slide-native-slide{{if and (eq $deckIndex 0) (eq $slideIndex 0)}} active{{end}}" data-native-slide data-deck-title="{{$deck.Title}}" data-slide-title="{{$slide.Title}}" data-slide-target="{{$slide.Target}}"{{if not (and (eq $deckIndex 0) (eq $slideIndex 0))}} hidden{{end}}>{{template "fragment" $slide}}</section>{{end}}{{end}}<nav class="slide-native-controls" aria-label="Slide navigation"><button type="button" class="slide-step" data-slide-previous aria-label="Previous slide" title="Previous slide">‹</button><button type="button" class="slide-step" data-slide-next aria-label="Next slide" title="Next slide">›</button></nav><button type="button" class="slide-exit-presentation" data-slide-exit-presentation hidden>Exit presentation</button></div></section>{{end}}
{{define "chapter"}}<section class="section chapter" id="{{.DOMID}}" data-chapter{{if .Deferred}} data-section-href="/api/section?target={{urlquery .Target}}"{{end}}><div class="section-head chapter-head"><button type="button" class="chapter-toggle" data-chapter-toggle aria-expanded="false" aria-controls="{{.DOMID}}--body" aria-label="Open {{.Title}}">{{template "twisty"}}</button><h2><a href="#{{.DOMID}}">{{.Title}}</a></h2><div class="section-actions">{{template "diff-control" .}}{{template "permalink" .DOMID}}{{template "review-controls" .}}</div></div>{{if .ChangeCount}}{{template "diff-template" .}}{{end}}<div class="chapter-body" id="{{.DOMID}}--body" data-chapter-body hidden>{{if .Deferred}}<p class="section-placeholder" data-section-placeholder>Loading this chapter…</p>{{else}}{{template "section-body" .}}{{end}}</div></section>{{end}}
{{define "section-body"}}{{if and (eq .Kind "chapter") .DirectoryManaged}}{{template "chapter-review-directory" .}}{{end}}{{template "threads" .Threads}}{{range .FragmentViews}}{{template "fragment" .}}{{end}}{{range .ChildViews}}{{template "section" .}}{{end}}{{end}}
{{define "section"}}<section class="section {{.Kind}}" id="{{.DOMID}}"><div class="section-head"><h2>{{.Title}}</h2><div class="section-actions">{{template "diff-control" .}}{{template "permalink" .DOMID}}{{template "review-controls" .}}</div></div>{{if .ChangeCount}}{{template "diff-template" .}}{{end}}{{template "section-body" .}}</section>{{end}}
{{define "diff-template"}}<template id="diffs-{{.DOMID}}">{{with .Attached}}{{template "attached-code" .}}{{end}}</template>{{end}}
{{define "attached-code"}}<div class="attached-code" data-attached-title="{{.Title}}"><header class="attached-code-summary">{{template "icon" "diff"}}<span>{{len .Files}} {{if eq (len .Files) 1}}file{{else}}files{{end}} · {{template "diff-counts" .}}{{if .EventCount}} · {{.EventCount}} file {{if eq .EventCount 1}}event{{else}}events{{end}}{{end}}</span><span class="attached-code-scope">{{.LinkedLineCount}} linked {{if eq .LinkedLineCount 1}}line{{else}}lines{{end}} highlighted{{if .LinkedEvents}} · {{.LinkedEvents}} linked {{if eq .LinkedEvents 1}}event{{else}}events{{end}}{{end}}</span></header><div class="attached-file-list">{{range .Files}}<details class="attached-file" data-file-diff-href="/api/file-diff?file={{urlquery .Path}}&amp;target={{urlquery .Target}}" data-attached-target="{{.Target}}"><summary>{{template "twisty" }}{{template "ficon" .Path}}<span class="attached-file-main"><code>{{.Path}}</code><span class="attached-file-note {{if .MissingSummary}}missing{{end}}">{{.Summary}}</span></span><span class="attached-file-counts">{{template "diff-counts" .}}{{if .Events}} · {{.Events}} {{if eq .Events 1}}event{{else}}events{{end}}{{end}} · {{.LinkedLines}} linked</span></summary>{{template "review-file-diff-surface" (reviewDiffSurface .Path .Href)}}</details>{{end}}</div></div>{{end}}
{{define "landmark-affordance"}}<span class="landmark-affordance" data-landmark-affordance>{{template "permalink" .DOMID}}{{template "diff-control" .}}{{if .ItemMeta}}{{template "review-comment-button" .}}{{end}}</span>{{end}}
{{define "fragment"}}{{if .Deferred}}{{template "fragment-descriptor" .}}{{else}}{{template "fragment-content" .}}{{end}}{{end}}
{{define "fragment-descriptor"}}<article class="fragment deferred" id="{{.DOMID}}" data-target="{{.Target}}" data-fragment-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" data-fragment-href="/api/fragment?target={{urlquery .Target}}" tabindex="0"><div class="fragment-head"><div class="fragment-actions">{{template "permalink" .DOMID}}{{template "annotation-tools-button" .}}{{template "review-controls" .}}</div></div><div class="fragment-stage"><p class="fragment-placeholder" data-fragment-placeholder>Loading this explanation…</p></div></article>{{end}}
{{define "fragment-content"}}<article class="fragment" id="{{.DOMID}}" data-target="{{.Target}}" data-fragment-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" tabindex="0"><div class="fragment-head"><div class="fragment-actions">{{if .ChangeCount}}{{template "diff-open-button" .}}{{end}}{{if .LandmarkViews}}<details class="landmark-menu"><summary aria-label="Jump to a marked place" title="Marked places">{{template "icon" "list"}}</summary><div class="landmark-list">{{range .LandmarkViews}}<div><a href="#{{.DOMID}}">{{.Label}}</a>{{if .ChangeCount}}{{template "diff-open-button" .}}{{end}}{{template "permalink" .DOMID}}</div>{{end}}</div></details>{{end}}{{template "permalink" .DOMID}}{{template "annotation-tools-button" .}}{{template "review-controls" .}}</div></div>{{range .LandmarkViews}}<span id="{{if eq .Selector.Type "heading"}}landmark-meta-{{end}}{{.DOMID}}" class="landmark-target" data-landmark-target data-landmark-anchor="{{.DOMID}}" data-landmark-type="{{.Selector.Type}}" data-element-id="{{.Selector.ElementID}}" data-heading-id="{{.Selector.HeadingID}}" data-exact="{{.Selector.Exact}}" data-prefix="{{.Selector.Prefix}}" data-suffix="{{.Selector.Suffix}}"><template data-landmark-affordance-template>{{template "landmark-affordance" .}}</template></span>{{if .ChangeCount}}{{template "diff-template" .}}{{end}}{{end}}<div class="fragment-stage">{{if .Markdown}}<div class="fragment-markdown" data-selectable>{{.Markdown}}</div>{{else if .Plain}}<pre class="plain" data-selectable>{{.Plain}}</pre>{{else if .Interactive}}<iframe class="fragment-frame" data-fragment-frame sandbox="allow-scripts" src="{{.URL}}" title="{{.Title}}"></iframe>{{else if .Image}}<img class="fragment-image" src="{{.URL}}" alt="{{.Title}}">{{else}}<a href="{{.URL}}">Open file</a>{{end}}{{range .LandmarkViews}}{{if .Region}}<div class="landmark-hotspot" data-landmark-visual="{{.DOMID}}" data-x="{{.Region.X}}" data-y="{{.Region.Y}}" data-width="{{.Region.Width}}" data-height="{{.Region.Height}}">{{template "landmark-affordance" .}}</div>{{end}}{{end}}<svg class="review-overlay" viewBox="0 0 1000 1000" preserveAspectRatio="none">{{range .AnnotationThreads}}{{$thread := .}}{{if or (eq .Anchor.Type "region") (eq .Anchor.Type "drawing")}}<g data-annotation-entity data-thread-id="{{.ID}}" data-target="{{.Target}}" data-anchor-type="{{.Anchor.Type}}" data-thread-state="{{.State}}">{{range $index,$shape := .Anchor.Shapes}}{{$color := annotationColor $shape.Color}}{{if eq $shape.Type "rect"}}<rect class="annotation selectable" data-shape-index="{{$index}}" stroke="{{$color}}" fill="{{$color}}" fill-opacity=".22" x="{{coord $shape.X}}" y="{{coord $shape.Y}}" width="{{coord $shape.Width}}" height="{{coord $shape.Height}}"/>{{else if eq $shape.Type "ellipse"}}<ellipse class="annotation selectable" data-shape-index="{{$index}}" stroke="{{$color}}" fill="{{$color}}" fill-opacity=".22" cx="{{coord $shape.X}}" cy="{{coord $shape.Y}}" rx="{{coord $shape.Width}}" ry="{{coord $shape.Height}}"/>{{else if eq $shape.Type "line"}}<line class="annotation path selectable" data-shape-index="{{$index}}" stroke="{{$color}}" x1="{{coord $shape.X}}" y1="{{coord $shape.Y}}" x2="{{coord $shape.Width}}" y2="{{coord $shape.Height}}"/>{{else if eq $shape.Type "path"}}<polyline class="annotation path selectable" data-shape-index="{{$index}}" stroke="{{$color}}" points="{{points $shape.Points}}"/>{{end}}{{end}}</g>{{end}}{{end}}</svg>{{range .AnnotationThreads}}{{if eq .Anchor.Type "note"}}{{template "sticky-note" .}}{{end}}{{end}}{{range .AnnotationThreads}}{{template "annotation-bubble" .}}{{end}}</div>{{template "threads" .Threads}}{{range .LandmarkViews}}{{template "threads" .Threads}}{{end}}{{if .ChangeCount}}{{template "diff-template" .}}{{end}}</article>{{end}}

{{define "sticky-note"}}{{$noteID := printf "%s--note" (domID (printf "thread:%s" .ID))}}<div class="sticky-note" id="{{$noteID}}" data-sticky-note data-thread-id="{{.ID}}" data-target="{{.Target}}" data-thread-state="{{.State}}" data-x="{{.Anchor.Note.X}}" data-y="{{.Anchor.Note.Y}}" data-color="{{noteColor .Anchor.Note.Color}}" style="--note-color:{{noteColor .Anchor.Note.Color}};left:{{percent .Anchor.Note.X}}%;top:{{percent .Anchor.Note.Y}}%" tabindex="0" role="note" aria-label="Sticky note by {{if .CreatedBy}}{{.CreatedBy}}{{else}}an unattributed reviewer{{end}}"><p class="sticky-note-body" data-sticky-text>{{.Anchor.Note.Text}}</p><span class="sticky-note-actions">{{template "permalink" $noteID}}</span></div>{{end}}

{{define "annotation-bubble"}}<div class="annotation-bubble {{.State}}{{if .Placed}} placed{{end}}" data-annotation-bubble data-thread-id="{{.ID}}" data-anchor-type="{{.Anchor.Type}}" data-thread-state="{{.State}}"{{if .Placed}} style="left:{{percent .X}}%;top:{{percent .Y}}%"{{end}}><button type="button" class="annotation-bubble-toggle" data-annotation-bubble-toggle aria-expanded="false" aria-controls="{{.PanelID}}" aria-label="{{len .Messages}} {{if eq (len .Messages) 1}}comment{{else}}comments{{end}} on this {{.Label}}" title="{{len .Messages}} {{if eq (len .Messages) 1}}comment{{else}}comments{{end}} on this {{.Label}}">{{template "icon" "comment"}}<span class="annotation-bubble-count">{{len .Messages}}</span></button><div class="annotation-bubble-panel" id="{{.PanelID}}" data-annotation-bubble-panel hidden>{{template "threads" .Comments}}</div></div>{{end}}

{{define "diff-surface-row"}}{{if eq .Kind "context"}}<div class="diff-row context{{if .Linked}} linked-evidence{{end}}" data-context-row role="group" aria-label="Unchanged line {{.NewLine}}"><span class="line-no">{{.OldLine}}</span><span class="line-no">{{.NewLine}}</span><span class="sign" aria-hidden="true"> </span><code class="code-line" data-code>{{.Content}}</code><span></span></div>{{else if eq .Kind "event"}}<div class="diff-row event{{if .Linked}} linked-evidence{{end}}"{{with .Atom}} data-diff-ref="{{.URI}}" data-target="{{.Target}}"{{end}}><span class="line-no">•</span><span class="line-no">•</span><span class="sign" aria-hidden="true">↳</span><span class="code-line">{{.Event}} {{if .OldPath}}{{.OldPath}} → {{.NewPath}}{{else}}{{.Path}}{{end}}</span>{{with .Atom}}<span class="line-actions"><button type="button" class="icon-button" data-diff-action="comment" aria-label="Comment on this file event" title="Comment">{{template "icon" "comment"}}</button></span>{{template "diff-threads" .Threads}}{{end}}</div>{{else}}{{$atom := .Atom}}<div class="diff-row {{.Kind}} {{if $atom.Selected}}selected{{end}}{{if .Linked}} linked-evidence{{end}}" data-diff-row data-side="{{.Kind}}" data-line="{{if eq .Kind "old"}}{{.OldLine}}{{else}}{{.NewLine}}{{end}}" data-path="{{.Path}}" data-diff-ref="{{$atom.URI}}" data-target="{{$atom.Target}}" role="group" aria-label="{{if eq .Kind "old"}}Removed old line {{.OldLine}}{{else}}Added new line {{.NewLine}}{{end}}"><span class="line-no">{{if .OldLine}}{{.OldLine}}{{end}}</span><button class="line-select" type="button" data-line-select aria-label="Select {{if eq .Kind "old"}}removed line {{.OldLine}}{{else}}added line {{.NewLine}}{{end}}">{{if .NewLine}}{{.NewLine}}{{end}}</button><span class="sign" aria-hidden="true">{{if eq .Kind "old"}}−{{else}}+{{end}}</span><code class="code-line" data-code>{{.Content}}</code><span class="line-actions"><button type="button" class="icon-button" data-diff-action="comment" aria-label="Comment on this line" title="Comment">{{template "icon" "comment"}}</button><button type="button" class="icon-button" data-diff-action="suggestion" aria-label="Suggest a replacement for this line" title="Suggest">{{template "icon" "pen"}}</button></span>{{template "diff-threads" $atom.Threads}}</div>{{end}}{{end}}
{{define "diff-threads"}}{{if .}}<div class="diff-thread-wrap">{{template "threads" .}}</div>{{end}}{{end}}
{{define "file-owners"}}<div data-file-owners-response>{{if .Groups}}{{template "related-saga-groups" .Groups}}{{else}}<p>{{.RelatedEmpty}}</p>{{end}}</div>{{end}}
{{define "message-fragments"}}{{range .}}<div class="message-fragment">{{if .Markdown}}<div class="fragment-markdown">{{.Markdown}}</div>{{else if .Interactive}}<iframe class="fragment-frame" sandbox="allow-scripts" src="{{.URL}}"></iframe>{{else if .Image}}<img class="fragment-image" src="{{.URL}}" alt="attachment">{{else}}<pre class="plain">{{.Plain}}</pre>{{end}}</div>{{end}}{{end}}
{{define "threads"}}{{if .}}<div class="threads">{{range .}}{{$thread := .}}{{$threadID := domID (printf "thread:%s" .ID)}}<article class="thread {{.State}} {{.Kind}}" id="{{$threadID}}"><div class="thread-meta"><span title="{{.AttributionDetail}}">{{.CreatedBy}}</span> · {{.CreatedAt.Format "2006-01-02 15:04 MST"}} · {{if .Kind}}{{.Kind}}{{else}}{{anchorLabel .Anchor.Type}}{{end}}{{if .StateAuthor}} · {{.State}} by <span title="{{.StateDetail}}">{{.StateAuthor}}</span>{{else}} · {{.State}}{{end}}{{template "permalink" $threadID}}</div>{{if .Anchor.Text}}<div class="text-anchor" data-text-target="{{.Target}}" data-thread-id="{{.ID}}" data-exact="{{.Anchor.Text.Exact}}" data-text-color="{{annotationColor .Anchor.Text.Color}}">“{{.Anchor.Text.Exact}}”</div>{{end}}{{if .Anchor.Note}}<div class="note-anchor" style="--note-color:{{noteColor .Anchor.Note.Color}}">{{.Anchor.Note.Text}}</div>{{end}}{{if .Suggestion}}<code class="suggestion-code">{{.Suggestion.Replacement}}</code>{{end}}{{range $index,$message := .Messages}}{{$messageID := domID (printf "message:%s" $message.ID)}}<div class="message" id="{{$messageID}}"><div class="thread-meta" title="{{$message.AttributionDetail}}">{{$message.Author}} · {{$message.CreatedAt.Format "2006-01-02 15:04 MST"}}{{template "permalink" $messageID}}</div>{{template "message-fragments" (index $thread.MessageViews $index)}}</div>{{end}}<form class="reply" method="post" action="/api/reply" enctype="multipart/form-data"><input type="hidden" name="thread" value="{{.ID}}"><input type="hidden" name="target" value="{{.Target}}"><input name="body" placeholder="Reply" aria-label="Reply"><button>Reply</button><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" aria-label="Attach files" multiple></form><form class="thread-state" method="post" action="/api/thread-state"><input type="hidden" name="thread" value="{{.ID}}"><input type="hidden" name="target" value="{{.Target}}"><button class="btn-subtle" name="state" value="{{if eq .State "resolved"}}open{{else}}resolved{{end}}">{{if eq .State "resolved"}}Reopen{{else}}Resolve{{end}}</button></form></article>{{end}}</div>{{end}}{{end}}`
